    def touch_way(self, row, way, fill=False):
        if self.replacement == "LRU" or (
                self.replacement == "FIFO" and fill):
            self.clock += 1
            self.touched[row][way] = self.clock
        elif self.replacement == "PLRU":
            lo, hi, node = 0, self.ways, 1
            while hi - lo > 1:
                mid = (lo + hi) // 2
                if way < mid:
                    self.bits[row][node] = 1
                    hi = mid
                    node *= 2
                else:
                    self.bits[row][node] = 0
                    lo = mid
                    node = node * 2 + 1
    def touch(self, block):
        where = self.locate(block)
        if where is not None:
            self.touch_way(*where, fill=False)
def requester(protocol, old, op, other_has_line):
    if protocol == "VI":
        if op == "R":
            return ("BusRd", "V") if old == "I" else (None, "V")
        return ("BusWr", "I" if old == "I" else "V")

    if old == "I":
        if op == "W":
            return "BusRdX", "M"
        if protocol in ("MESI", "MOESI"):
            return "BusRd", "S" if other_has_line else "E"
        return "BusRd", "S"
    if op == "R":
        return None, old
    if old in ("M", "E"):
        return None, "M"
    if old in ("S", "O"):
        return "BusUpgr", "M"
    raise ValueError((protocol, old, op))
